class Command(BaseCommand):
    help = "Create safe starter content without fake clients or testimonials."
    def handle(self, *args, **options):
        settings_obj, _ = SiteSettings.objects.get_or_create(pk=1)
        settings_obj.agency_name = "Your Agency"
        settings_obj.tagline = "Software & Digital Solutions"
        settings_obj.description = "We design and engineer custom software, AI assistants, data systems, and operational automations for ambitious teams."
        settings_obj.email = "hello@example.com"
        settings_obj.address = "Serving clients worldwide"
        settings_obj.seo_title = "Your Agency | Software & Digital Solutions"
        settings_obj.seo_description = "Custom software, AI chatbot, web scraping, automation, and B2B lead generation solutions."
        settings_obj.save()
        HeroSection.objects.update_or_create(pk=1, defaults={"eyebrow": "Software engineering for operational teams", "heading": "Turn operational friction into working software.", "highlighted_text": "working software", "description": "We build secure digital products, intelligent assistants, data pipelines, and automations around the way your team actually works.", "primary_button_text": "Start your project", "primary_button_url": "/contact", "secondary_button_text": "View our work", "secondary_button_url": "/projects"})
        AboutSection.objects.update_or_create(pk=1, defaults={"eyebrow": "About the agency", "heading": "A focused technology partner for consequential work.", "introduction": "We combine product thinking, careful engineering, and direct collaboration to turn complex operational problems into useful software.", "mission": "Make reliable, business-ready software accessible to growing teams.", "vision": "Create digital systems that give people more time, clarity, and control.", "philosophy": "Business value before feature volume. Security and accessibility by design. Clear communication from discovery to launch. Maintainable systems over short-term shortcuts."})
        for index, (label, url) in enumerate((("Home", "/"), ("Services", "/services"), ("Projects", "/projects"), ("Technologies", "/technologies"), ("About", "/about"), ("Contact", "/contact"))):
            NavigationItem.objects.update_or_create(label=label, defaults={"url": url, "display_order": index, "is_cta": label == "Contact", "is_active": True})
        technology_data = [("Python", "Backend"), ("Django", "Backend"), ("Django REST Framework", "APIs"), ("React", "Frontend"), ("Tailwind CSS", "Frontend"), ("SQLite", "Data"), ("PostgreSQL", "Data"), ("Redis", "Infrastructure"), ("Celery", "Automation"), ("Docker", "Infrastructure")]
        technologies = {}
        for index, (name, category) in enumerate(technology_data):
            technologies[name], _ = Technology.objects.update_or_create(slug=slugify(name), defaults={"name": name, "category": category, "description": f"Production-focused {category.lower()} capability.", "display_order": index, "is_active": True})
        for index, (title, summary, icon, features) in enumerate(SERVICES):
            service, _ = Service.objects.update_or_create(slug=slugify(title), defaults={"title": title, "short_description": summary, "description": summary, "outcome": "A maintainable solution designed around the way your operation actually works.", "icon_name": icon, "display_order": index, "is_featured": True, "is_active": True})
            service.features.all().delete()
            ServiceFeature.objects.bulk_create([ServiceFeature(service=service, title=feature, display_order=order) for order, feature in enumerate(features)])
        for index, data in enumerate(PROJECTS):
            category, _ = ProjectCategory.objects.get_or_create(slug=slugify(data["category"]), defaults={"name": data["category"], "display_order": index})
            project, _ = Project.objects.update_or_create(slug=slugify(data["title"]), defaults={"title": data["title"], "subtitle": data["subtitle"], "category": category, "overview": data["overview"], "problem": data["problem"], "solution": data["solution"], "result": data["result"], "display_order": index, "is_featured": True, "is_active": True})
            project.features.all().delete()
            ProjectFeature.objects.bulk_create([ProjectFeature(project=project, title=feature, display_order=order) for order, feature in enumerate(data["features"])])
            project.technologies.set([technologies[name] for name in data["technologies"] if name in technologies])
        CTASection.objects.update_or_create(name="Primary", defaults={"eyebrow": "Start a conversation", "heading": "Have a serious problem worth solving?", "description": "Tell us what is slowing your team down. We will help shape the right next step.", "primary_button_text": "Discuss your project", "primary_button_url": "/contact", "secondary_button_text": "Explore our work", "secondary_button_url": "/projects"})
        Page.objects.update_or_create(slug="privacy-policy", defaults={"title": "Privacy Policy", "eyebrow": "Legal", "summary": "How information submitted through this website is handled.", "content": "We collect only the information you choose to provide so we can respond to your inquiry. We do not sell personal information. Access is limited to authorized team members and service providers required to operate the website. Replace this draft with legal language reviewed for your jurisdiction before public launch."})
        Page.objects.update_or_create(slug="terms-and-conditions", defaults={"title": "Terms & Conditions", "eyebrow": "Legal", "summary": "General terms governing use of this website.", "content": "Website content is provided for general information and does not create a client relationship. Project scope, fees, ownership, warranties, and support are governed by a separate written agreement. Replace this draft with legal language reviewed for your jurisdiction before public launch."})
        FooterLink.objects.update_or_create(label="Privacy Policy", defaults={"group": "Legal", "url": "/privacy-policy", "display_order": 1})
        FooterLink.objects.update_or_create(label="Terms & Conditions", defaults={"group": "Legal", "url": "/terms-and-conditions", "display_order": 2})
        self.stdout.write(self.style.SUCCESS("Starter content created. No clients or testimonials were fabricated."))
